// === Tab: mySketch ===
/**
A minimal implementation of K-means clustering built from scratch in p5.js.

Random points organize themselves into clusters by repeatedly assigning to the nearest centroid and recalculating their shared center. The system stabilizes into distinct regions through simple local rules.

Click to regenerate a new configuration.

**/

let points = [];
let centroids = [];
let k = 8;
let colors = ["blue", "green", "red", "orange", "cyan", "purple", "yellow", "pink"];

function setup() {
	createCanvas(windowWidth, windowHeight);



	for(let i = 0; i < 800;i++){
		points.push({
			x: random(width),
			y: random(height),
			cluster: 0
		});
	}


	for(let i = 0;i<k;i++){
		centroids.push({
			x:random(width),
			y: random(height),
		})
	}
}

function draw() {
	background(0);
	assignClusters();
	updateCentroids();
	drawPoints();
	movePoints();
	drawCentroids();
	drawConnections();
}


function assignClusters(){


   for(let p of points){
	   let closestIndex = 0;
	   let closestDistance = Infinity;
	   for(let i = 0;i<centroids.length;i++){
			let centroid = centroids[i];

			let d = dist(p.x, p.y, centroid.x, centroid.y);
			if(d < closestDistance){
				closestDistance = d;
				closestIndex = i;
			}
		}
	   p.cluster = closestIndex;
	}

}


function updateCentroids(){

	for(let i = 0;i<k;i++){
		let sumX = 0;
		let sumY = 0;
		let count = 0;
		 for(let p of points){
			 if(p.cluster === i){
				 sumX+= p.x;
				 sumY+= p.y;
				 count++;
			 }
		 }


		if(count > 0){
			centroids[i].x = lerp(centroids[i].x, sumX / count, 0.05);
		   centroids[i].y = lerp(centroids[i].y, sumY / count, 0.05);
		}

	}
}

function drawPoints() {


  noStroke();

  for (let p of points) {
    fill(colors[p.cluster]);
    circle(p.x, p.y, 10);
  }
}


function drawCentroids() {
  fill(0);
  // stroke(255);
  // strokeWeight(5);

  for (let c of centroids) {
    circle(c.x, c.y, 25);
  }
}

function drawConnections(){
	strokeWeight(1);
	for(let p of points){
		 let c = centroids[p.cluster];
		 stroke([colors[p.cluster]]);
		 line(p.x, p.y, c.x, c.y)
	}
}

function movePoints() {
  for (let p of points) {
    p.x += random(-1, 1);
    p.y += random(-1, 1);

    p.x = constrain(p.x, 0, width);
    p.y = constrain(p.y, 0, height);
  }
}

function mousePressed() {
   resetSketch();
	redraw();
}

function resetSketch() {
  points = [];
  centroids = [];

  for (let i = 0; i < 150; i++) {
    points.push({
      x: random(width),
      y: random(height),
      cluster: 0
    });
  }

  for (let i = 0; i < k; i++) {
    centroids.push({
      x: random(width),
      y: random(height)
    });
  }
}

